def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    # Split the input string into individual letters
    letters = test.split()

    # Create an empty dictionary to store the letter counts
    count_dict = {}

    # Iterate over the letters and increment the count for each letter in the dict
    for letter in letters:
        if letter not in count_dict:
            count_dict[letter] = 1
        else:
            count_dict[letter] += 1

    # Find the key with the highest value in the dict
    max_key = max(count_dict, key=count_dict.get)

    # If there are multiple keys with the same value, return all of them
    if count_dict[max_key] == len(letters):
        return {letter: count for letter, count in count_dict.items()}
    else:
        return {max_key: count_dict[max_key]}
